#!/usr/bin/env python3
from __future__ import annotations

import base64
import json
from pathlib import Path
import zlib

ARCHIVE_B64 = """"""

def main() -> None:
    repo = Path(__file__).resolve().parents[2]
    payload = zlib.decompress(base64.b64decode(ARCHIVE_B64.encode("ascii")))
    files = json.loads(payload.decode("utf-8"))
    for relative, content in files.items():
        path = repo / relative
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(content, encoding="utf-8", newline="")
    print(json.dumps({"status":"INSTALLED","file_count":len(files),"trade_authority":"NONE","orders":0}, ensure_ascii=False))

if __name__ == "__main__":
    main()
